or \\\"\\\"\"},\n    \"need\": {\"type\": \"string\", \"description\": \"What the inquirer asks for, or \\\"\\\"\"},\n    \"label\": {\"type\": \"string\", \"enum\": [\"trade inquiry\", \"not an inquiry\"]}\n  }\n}";
